package com.wizzadrds.theworldremembers.voice; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class VoiceProfileTest{@Test void profileValuesAreStable(){var p=new VoiceProfile("es-ES","local-piper",VoiceTemperament.WARM,5,-10,70);assertEquals("es-ES",p.language());assertEquals(70,p.expressiveness());} @Test void dangerOverridesDeliveryTemperament(){var p=new VoiceProfile("es-ES","local-piper",VoiceTemperament.CHEERFUL,0,0,50);var d=VoiceDelivery.adapt(p,0,true,false,false);assertEquals(VoiceTemperament.NERVOUS,d.temperament());assertTrue(d.rate()>0);}}
